mapper.select:
SELECT btd.id, btd.code as code, btd.so_id as soId, btd.so_code as soCode, btd.receiver_name as receiverName, btd.warehouse_org_id, btd.warehouse_org_name, btd.platform_order_code, btd.status as status, btd.delivery_warehouse_id, btd.delivery_warehouse_name as deliveryWarehouseName, btd.delivery_method as deliveryMethod, btd.warehouse_operation_type as warehouseOperationType, btd.delivery_time, btd.create_time, btd.create_user_name as createUserName, btd.error_message as errorMessage, btd.push_type as pushType, btd.is_api_delivery as isApiDelivery, btd.customer_id as customerId, btd.customer_name as customerName, btdd.id as detailId, btdd.sku_id as skuId, btdd.sku_no, btdd.delivery_qty, btdd.delivery_sku_id, btdd.delivery_sku_no, btdd.warehouse_platform_sku, btdd.per_box_qty, btdd.box_qty, btd.remark FROM b2b_third_delivery btd LEFT JOIN b2b_third_delivery_detail btdd ON btd.id = btdd.main_id AND btdd.is_deleted=false WHERE ${params.sqlMap.default} and btd.is_deleted=false ORDER BY
${item.field} ${item.sort}
btd.create_time desc
